module uart_transmitter #(parameter BAUD_RATE = 9600, parameter CLOCK_FREQ = 50000000) (  
    input wire clk,  
    input wire rst,  
    input wire tx_en,  
    input wire [7:0] data_in,  
    output reg tx  
);  

    localparam CLOCK_COUNT = CLOCK_FREQ / BAUD_RATE;  
    localparam IDLE = 3'b000, START = 3'b001, DATA = 3'b010, PARITY = 3'b011, STOP = 3'b100;  
    reg [2:0] state, next_state;  
    reg [3:0] bit_count;  
    reg [15:0] clock_counter;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            state <= IDLE;  
            tx <= 1;  
            clock_counter <= 0;  
            bit_count <= 0;  
        end else begin  
            state <= next_state;  
            if (next_state != IDLE) begin  
                clock_counter <= clock_counter + 1;  
            end else begin  
                clock_counter <= 0;  
            end  
        end  
    end  

    always @(*) begin  
        next_state = state;  
        case (state)  
            IDLE: begin  
                if (tx_en)  
                    next_state = START;  
            end  
            START: begin  
                if (clock_counter == CLOCK_COUNT - 1) begin  
                    next_state = DATA;  
                    bit_count = 0;  
                end  
            end  
            DATA: begin  
                if (clock_counter == CLOCK_COUNT - 1) begin  
                    if (bit_count < 8) begin  
                        tx = data_in[bit_count];  
                        bit_count = bit_count + 1;  
                    end else begin  
                        next_state = PARITY;  
                    end  
                end  
            end  
            PARITY: begin  
                if (clock_counter == CLOCK_COUNT - 1) begin  
                    tx = ^data_in; // Simple parity bit  
                    next_state = STOP;  
                end  
            end  
            STOP: begin  
                if (clock_counter == CLOCK_COUNT - 1) begin  
                    tx = 1; // Stop bit  
                    next_state = IDLE;  
                end  
            end  
        endcase  
    end  
endmodule

