module lfsr_8bit (
    input clk,
    input rst,
    output reg [7:0] lfsr_out
);
    wire feedback;

    // Feedback logic based on the polynomial x^8 + x^6 + x^5 + x^4 + 1
    assign feedback = lfsr_out[7] ^ lfsr_out[5] ^ lfsr_out[4] ^ lfsr_out[3];

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            lfsr_out <= 8'b1; // Initialize the LFSR to a non-zero value
        end else begin
            lfsr_out <= {lfsr_out[6:0], feedback}; // Shift left and insert feedback
        end
    end
endmodule

