    reg [3:0] GPIO_OUT;
    reg clk;
    reg reset;
    reg write_enable;
    wire [3:0] GPIO_IN;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    gpio_controller dut (
        .GPIO_OUT(GPIO_OUT),
        .clk(clk),
        .reset(reset),
        .write_enable(write_enable),
        .GPIO_IN(GPIO_IN)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

        begin
            reset = 1;
            write_enable = 0;
            GPIO_OUT = 4'b0000;
            @(posedge clk);
            #1 reset = 0;
            @(posedge clk);
        end
        endtask
    task testcase001;

        begin
            $display("Test 001: Checking Reset State...");
            reset_dut();
            #1;

            check_outputs(4'b0000);
        end
        endtask

    task testcase002;

        begin
            $display("Test 002: Checking Inactive Write Enable...");
            reset_dut();
            GPIO_OUT = 4'b1111;
            write_enable = 0;
            @(posedge clk);
            #1;

            check_outputs(4'b0000);
        end
        endtask

    task testcase003;

        begin
            $display("Test 003: Checking Single Bit Toggle...");
            reset_dut();
            GPIO_OUT = 4'b0001;
            write_enable = 1;
            @(posedge clk);
            #1 write_enable = 0;
            #1;

            check_outputs(4'b0001);
        end
        endtask

    task testcase004;

        begin
            $display("Test 004: Checking All-Bit Toggle...");
            reset_dut();
            GPIO_OUT = 4'b1111;
            write_enable = 1;
            @(posedge clk);
            #1 write_enable = 0;
            #1;

            check_outputs(4'b1111);
        end
        endtask

    task testcase005;

        begin
            $display("Test 005: Checking Double Toggle (Toggle back to 0)...");
