            write_enable = 1;
            GPIO_OUT = 4'b1010;
            @(posedge clk);
            GPIO_OUT = 4'b1010;
            @(posedge clk);
            #1 write_enable = 0;
            #1;

            check_outputs(4'b0000);
        end
        endtask

    task testcase006;

        begin
            $display("Test 006: Checking Sequential Partial Toggles...");
