module pll_8x (  
    input clk_in,  
    input reset,  
    input enable,  
    output reg clk_out  
);  
    reg [2:0] counter;  

    always @(posedge clk_in or posedge reset) begin  
        if (reset) begin  
            counter <= 3'b000;  
            clk_out <= 0;  
        end else if (enable) begin  
            if (counter == 3'b111) begin  
                clk_out <= ~clk_out;  
                counter <= 3'b000;  
            end else begin  
                counter <= counter + 1;  
            end  
        end  
    end  
endmodule

