    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= 128'b0;
            ciphertext <= 128'b0;
            ready <= 1'b0;
        end else begin
            // Start AES Encryption process
            state <= plaintext; // Initial state
            // Call key expansion and perform rounds
