module run_length_encoder (  
    input clk,  
    input rst,  
    input bit_in,  
    output reg [7:0] count_out,  
    output reg bit_out,  
    output reg valid  
);  
    reg [7:0] count;  
    reg last_bit;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            count <= 0;  
            count_out <= 0;  
            valid <= 0;  
            last_bit <= 0;  
        end else begin  
            if (bit_in == last_bit) begin  
                count <= count + 1;  
            end else begin  
                if (count > 0) begin  
                    count_out <= count;  
                    bit_out <= last_bit;  
                    valid <= 1;  
                end  
                count <= 1;  
                last_bit <= bit_in;  
            end  
        end  
    end  

    always @(posedge clk) begin  
        if (valid) begin  
            valid <= 0;  
        end  
    end  
endmodule

