module RSA_Encryption(
    input [7:0] plaintext,
    input [11:0] e,
    input [11:0] n,
    input clk,
    input start,
    output reg [11:0] ciphertext,
    output reg done
);
    reg [11:0] result;
    reg [7:0] base;
    reg [11:0] exp;
    reg [11:0] modulus;
    reg [3:0] state;

    always @(posedge clk) begin
        if (start) begin
            base <= plaintext;
            exp <= e;
            modulus <= n;
            result <= 1;
            state <= 0;
            done <= 0;
        end else begin
            case (state)
                0: begin
                    if (exp == 0) begin
                        done <= 1;
                        ciphertext <= result;
                        state <= 4; // Go to done state
                    end else if (exp[0] == 1) begin
                        result <= (result * base) % modulus;
                    end
                    exp <= exp >> 1;
                    base <= (base * base) % modulus;
                    state <= 1;
                end
                1: state <= 0; // Go back to check exp again
                4: state <= 4; // Stay in done state
            endcase
        end
    end
endmodule

