`timescale 1ns/1ps

module qr_decomposition_tb;

    // Testbench signals (combinational circuit)
    reg [15:0] a11;
    reg [15:0] a12;
    reg [15:0] a21;
    reg [15:0] a22;
    wire [15:0] q11;
    wire [15:0] q12;
    wire [15:0] q21;
    wire [15:0] q22;
    wire [15:0] r11;
    wire [15:0] r12;
    wire [15:0] r21;
    wire [15:0] r22;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    qr_decomposition dut (
        .a11(a11),
        .a12(a12),
        .a21(a21),
        .a22(a22),
        .q11(q11),
        .q12(q12),
        .q21(q21),
        .q22(q22),
        .r11(r11),
        .r12(r12),
        .r21(r21),
        .r22(r22)
    );
    task set_matrix;

        input [15:0] v11;
        input [15:0] v12;
        input [15:0] v21;
        input [15:0] v22;
        begin
            a11 = v11;
            a12 = v12;
            a21 = v21;
            a22 = v22;
        end
        endtask

    task testcase001;

        begin
            test_num = test_num + 1;
            $display("\nTestcase %0d: Identity Matrix", test_num);
            set_matrix(16'h1000, 16'h0000,
